String handle(Exception e) {
  if (e instanceof ValidationException) return "400: " + e.getMessage();
  if (e instanceof ProductNotFoundException) return "404: " + e.getMessage();
  if (e instanceof InsufficientStockException) return "409: " + e.getMessage();
  if (e instanceof DataAccessException) return "500: blad techniczny";
  return "500: nieznany blad";
}

private RuntimeException translate(SQLException e) {
  return switch (e.getSQLState()) {
    case "23505" -> new DuplicateEmailException("...");
    case "23514" -> new ValidationException("...", "narusza CHECK");
    default -> new DataAccessException("...", e);
  };
}

