int consecutiveFailures = 0;
void buyProductWithBreaker(long id) {
  if (consecutiveFailures >= 3) throw new ServiceUnavailableException();
  try { buyProduct(id); consecutiveFailures = 0; }
  catch (DataAccessException e) { consecutiveFailures++; throw e; }
}

